const ctx = typeof $json.context==='string'?JSON.parse($json.context):$json.context;
const agentResult=$('Olivia · Orquestador').item.json;
const raw = typeof agentResult.output==='string' ? JSON.parse(agentResult.output) : (agentResult.output ?? {});
const allowed = new Set(['early_access','products','orders','support','opt_out','reference', ...(ctx.document_index??[]).flatMap(d=>d.packages??[])].filter(x=>typeof x==='string'&&!['internal_ops','orchestrator','always'].includes(x)));
const packages = [...new Set((raw.knowledge_packages??[]).filter(x=>allowed.has(x)))].slice(0,3);
const tags = ctx.contact?.tags ?? [];
const registered = tags.includes('bf2026_early_access');
const literalStop = /^(?:stop|baja|unsubscribe|no me escribas m[aá]s|no me escrib[aá]is m[aá]s|no quiero recibir m[aá]s mensajes)[\s.!]*$/i.test(String(ctx.batch_text??'').trim());
const decision = {
 ...raw,
 knowledge_packages:packages,
 selected_document_ids:[...new Set((raw.selected_document_ids??[]).filter(id=>(ctx.document_index??[]).some(d=>d.id===id && !(d.packages??[]).some(t=>['internal_ops','orchestrator','always'].includes(t)))))].slice(0,8),
 product_ids:(raw.product_ids??[]).filter(id=>(ctx.products??[]).some(p=>p.id===id)).slice(0,4),
 opt_out:literalStop||raw.opt_out===true,
 opt_out_scope:literalStop?'whatsapp':(['email','all'].includes(raw.opt_out_scope)?raw.opt_out_scope:'whatsapp'),
 needs_human:raw.needs_human===true,
 early_access_action:registered?'already_registered':(['offer_registration','registration_requested'].includes(raw.early_access_action)?raw.early_access_action:'none'),
 summary:String(raw.summary??ctx.lead_state?.summary??'').slice(0,2400),
 pending_question:String(raw.pending_question??'').slice(0,300),
 prompt_version:'bf26-v2'
};
if(decision.opt_out) { decision.selected_document_ids=decision.selected_document_ids.filter(id=>(ctx.document_index??[]).some(d=>d.id===id&&(d.packages??[]).includes('opt_out'))); decision.early_access_action='none'; decision.product_ids=[]; decision.knowledge_packages=['opt_out']; decision.pending_question=''; }
if(registered && decision.intent==='early_access' && !/email|correo/i.test(decision.pending_question)) decision.pending_question='';
if(/(?:qu[eé].*(?:stop|baja)|(?:stop|baja).*significa)/i.test(ctx.batch_text??'')) { decision.pending_question=''; decision.response_brief='Explica el significado de STOP sin ofrecer tramitar una baja ni hacer preguntas.'; }
if(decision.needs_human) decision.pending_question='';
if(decision.intent==='early_access' && !/(?:jengibre|canela|menta|café|cafe|kema|magnesio|mg4|col[aá]geno)/i.test(ctx.batch_text??'')) decision.product_ids=[];

if(!/(?:receta|recetario|gu[ií]a|documento|recurso)/i.test(ctx.batch_text??'')) decision.knowledge_packages=decision.knowledge_packages.filter(x=>x!=='reference');

decision.lead_score=Number.isInteger(raw.lead_score)?Math.max(0,Math.min(100,raw.lead_score)):(ctx.score?.automatic??0);
decision.score_reason=String(raw.score_reason??'Valoración comercial actual').slice(0,300);
decision.registration_evidence=String(raw.registration_evidence??'').slice(0,1000);
decision.captured_email=String(raw.captured_email??'').trim().toLowerCase().slice(0,254);
decision.email_opt_in=raw.email_opt_in===true;
decision.suggested_stage=raw.suggested_stage??'none';
decision.commercial_updates=(Array.isArray(raw.commercial_updates)?raw.commercial_updates:[]).filter(e=>['interest','avoid','order_inquiry'].includes(e.kind) && String(e.evidence??'').trim() && String(ctx.batch_text??'').toLowerCase().includes(String(e.evidence).toLowerCase())).slice(0,5).map(e=>({...e,product_id:(ctx.products??[]).some(p=>p.id===e.product_id)?e.product_id:''}));
if(!registered && decision.early_access_action==='offer_registration' && !decision.opt_out && !decision.needs_human) {
 decision.pending_question=decision.pending_question||'¿Quieres que te apunte al acceso prioritario al Black Friday y te avisemos por WhatsApp?';
 decision.response_brief=decision.response_brief||'Ofrece el alta aquí según la documentación de campaña seleccionada. Espera su aceptación.';
}
if((ctx.tool_results??[]).some(t=>t.operation==='save_atributos'&&t.result?.saved===true)) decision.commercial_updates=[];
if(decision.opt_out) { decision.commercial_updates=[]; decision.captured_email=''; decision.email_opt_in=false; }


const nameAlreadyAsked=(ctx.history??[]).filter(m=>m.direction==='outbound').slice(-3).some(m=>/(?:c[oó]mo te llamas|cu[aá]l es tu nombre|dime tu nombre)/i.test(m.body??''));
const declinesName=/(?:no quiero|prefiero no|no voy a).{0,35}(?:nombre|llamo|identificar)/i.test(ctx.batch_text??'');
if(!ctx.contact?.first_name && !nameAlreadyAsked && !declinesName && !decision.pending_question && !decision.opt_out && !decision.needs_human && !['human','pending_human'].includes(ctx.conversation?.handoff_status) && !['order','handoff','opt_out'].includes(decision.intent)) {
 decision.pending_question='¿Cómo te llamas?';
 decision.summary=(decision.summary+' Nombre solicitado.').slice(0,2400);
 decision.response_brief=String(decision.response_brief??'')+' Responde primero a su consulta y pregunta su nombre al final, sin hacer otra pregunta.';
}

if(!decision.pending_question) decision.response_brief=String(decision.response_brief??'').replace(/¿[^?]*\?/g,'').trim();
if(decision.needs_human) decision.response_brief='Confirma brevemente que la solicitud pasa a revisión del equipo. No introduzcas promoción ni pidas datos accesorios.';
if(ctx.conversation?.handoff_status==='human') decision.suppress_reply=true;
return {json:{...ctx,decision,payload_b64:Buffer.from(JSON.stringify({...ctx,decision}),'utf8').toString('base64')}};
